// Turn any failed execution into one readable alert.
const e = $json.execution || {}, wf = $json.workflow || {};
const msg = e.error?.message || 'Unknown error';
const node = e.lastNodeExecuted || e.error?.node?.name || 'n/a';
const when = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const h = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: {
  html: `🚨 <b>ERROR · ${h(wf.name)}</b>
━━━━━━━━━━━━━━━━
<b>Node:</b> ${h(node)}
<b>Error:</b> ${h(msg)}
<b>Time:</b> ${when}
<b>Execution:</b> ${h(e.url || e.id || 'n/a')}

No message was sent to any contact by this execution.`,
  subject: `⚠️ Waypoint engine: "${wf.name}" failed`,
  text: `Workflow: ${wf.name}
Node: ${node}
Error: ${msg}
Time: ${when}
Mode: ${e.mode || 'n/a'}
Execution: ${e.url || e.id || 'n/a'}

No action was sent to any contact by this execution.`,
  workflow: wf.name, node, msg, executionId: String(e.id || '')
}}];

const t = s => [{ type: 'text', text: { content: String(s).slice(0, 1900) } }];
return [{ json: { parent: { database_id: '84a655097a4449588604e918ae009c1b' }, properties: {
  'Run': { title: t(`${$now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd HH:mm')} · ERROR · ${$json.workflow}`) },
  'Workflow': { select: { name: 'Error handler' } },
  'Status': { select: { name: 'Failed' } },
  'Started': { date: { start: new Date().toISOString() } },
  'Execution ID': { rich_text: t($json.executionId) },
  'Errors': { number: 1 },
  'Notes': { rich_text: t(`${$json.node}: ${$json.msg}`) }
}}}];
